/**
 * Demo cohort, computed by the Timeline engine.
 *
 * demo-data.json is generated by scripts/generate_demo_fixtures.py, which
 * calls the real trajectory and FRAX code. Nothing here is hand-written, so
 * the landing page chart and the demo patient screens show exactly what the
 * shipped model produces. Regenerate after any engine change.
 *
 * These are synthetic patients. No real clinical data is in this repository.
 */

import type {
  AdherenceResponse,
  FraxResponse,
  PatientContext,
  ScanObservation,
  TrajectoryResponse,
} from '@boensity/shared-types'
import demoAdherence from './demo-adherence.json'
import demoData from './demo-data.json'

export interface DemoPatient {
  id: string
  name: string
  note: string
  patient: PatientContext
  scans: ScanObservation[]
  trajectory: TrajectoryResponse
  frax: FraxResponse
}

export const DEMO_PATIENTS = demoData.patients as unknown as DemoPatient[]

export function getDemoPatient(id: string): DemoPatient | undefined {
  return DEMO_PATIENTS.find((patient) => patient.id === id)
}

/**
 * The patient shown on the landing page.
 *
 * Chosen because the projection crosses the threshold inside three years,
 * which is the case the product exists for: someone a static DEXA report
 * would currently describe as "osteopenia, repeat in two years".
 */
export const FEATURED_PATIENT_ID = 'BN-4471'

export function getFeaturedPatient(): DemoPatient {
  const patient = getDemoPatient(FEATURED_PATIENT_ID)
  if (!patient) throw new Error('featured demo patient missing from demo-data.json')
  return patient
}

export function osteoporosisCrossing(patient: DemoPatient) {
  return patient.trajectory.crossings.find(
    (crossing) => crossing.band_entered === 'osteoporosis',
  )
}

/**
 * Adherence for a demo patient, from demo-adherence.json.
 *
 * Generated by scripts/generate_sync_fixtures.py against the real Sync engine
 * and anchored to a fixed date, so the band does not change depending on when
 * the page is opened.
 */
const ADHERENCE = demoAdherence as unknown as Record<string, AdherenceResponse>

export function getDemoAdherence(patientId: string): AdherenceResponse | undefined {
  return ADHERENCE[patientId]
}
